class Solution {
public:
    int maximumSaleItems(vector<vector<int>>& items, int budget) {
        int n = items.size();
        vector<int> count(n + 1, 0);
        int cheapest = INT_MAX;
        for (auto &x : items) {
            ++count[x[0]];
            cheapest = min(cheapest, x[1]);
        }
        vector<int> gain(n + 1, 0);
        for (int d = 1; d <= n; ++d)
            for (int v = d; v <= n; v += d)
                gain[d] += count[v];
        vector<pair<int,int>> boosted;
        long long totalBoost = 0;
        for (int i = 0; i < n; ++i) {
            int g = gain[items[i][0]] - 1;
            if (g > 0) {
                boosted.push_back({items[i][1], g});
                totalBoost += g;
            }
        }
        sort(boosted.begin(), boosted.end());
        vector<long long> qty(1, 0), cost(1, 0);
        for (auto &x : boosted) {
            qty.push_back(qty.back() + x.second);
            cost.push_back(cost.back() + 1LL * x.first * x.second);
        }
        auto minCost = [&](long long target) -> long long {
            long long t = target / 2;
            // Only boosted units costing less than two ordinary copies help.
            long long useful = 0;
            for (auto &p : boosted) {
                if (p.first >= 2LL * cheapest) break;
                useful += p.second;
            }
            t = min(t, useful);
            int i = upper_bound(qty.begin(), qty.end(), t) - qty.begin() - 1;
            long long c = cost[i];
            if (i < (int)boosted.size()) c += (t - qty[i]) * boosted[i].first;
            return c + (target - 2 * t) * cheapest;
        };
        long long low = 0, high = 2LL * budget / cheapest;
        while (low < high) {
            long long mid = (low + high + 1) / 2;
            if (minCost(mid) <= budget) low = mid;
            else high = mid - 1;
        }
        return (int)low;
    }
};
